I reviewed the script and identified the exact causes of the errors you encountered:

### What Caused the Errors
1. **Line 72 (`catch (e)`)**: The variable name `e` was already declared as the function parameter in `function doPost(e)`. In Google Apps Script’s editor and JavaScript engines, re-declaring `e` inside a `catch` block causes a syntax/linter conflict (`Identifier 'e' has already been declared`).
2. **Line 44 (`e.postData`)**: If you clicked the **"Run"** button ▶️ in the Apps Script toolbar with `doPost` selected, Google Apps Script ran the function without an event object (`e` was `undefined`), triggering `TypeError: Cannot read property 'postData' of undefined` on line 44.
3. **Line 81 (`Utilities.formatDate`)**: The fallback timezone string could trigger `Invalid argument: timeZone` on accounts with non-standard locale settings.

---

### What Was Fixed
- **Resolved Variable Shadowing**: Cleaned all error arguments (`lockError`, `delErr`, etc.) so there are zero duplicate identifiers.
- **Null-Safe Event Handling**: If `doPost` is triggered directly without parameters, it now safely provides a fallback without crashing.
- **Failsafe Date Formatting**: Wrapped timezone extraction in a `try...catch` with automatic ISO fallback.
- **Added Safe One-Click Testing (`testSubmission`)**: Added a dedicated `testSubmission()` function to the script. You can select `testSubmission` in the Apps Script toolbar dropdown and click **"Run"** to authorize permissions and see a test lead created in your spreadsheet with zero errors.

---

### Updated Code to Paste into Google Apps Script

In your spreadsheet, open **Extensions** > **Apps Script**, delete whatever is currently in `Code.gs`, and replace it with this clean script:

```javascript
/**
 * ============================================================================
 * THE AFFLUENTACCELERATORS - MULTI-FORM GOOGLE SHEETS AUTOMATION SCRIPT
 * ============================================================================
 */

// POST endpoint: receives form submissions from the website
function doPost(e) {
  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(30000);
  } catch (lockError) {
    return ContentService.createTextOutput(JSON.stringify({
      status: "error",
      message: "Server busy, could not acquire lock. Please try again."
    })).setMimeType(ContentService.MimeType.JSON);
  }

  try {
    // Graceful payload extraction: handles JSON bodies, form parameters, or direct calls
    var payload = {};
    if (e && e.postData && e.postData.contents) {
      try {
        payload = JSON.parse(e.postData.contents);
      } catch (jsonErr) {
        payload = (e && e.parameter) ? e.parameter : {};
      }
    } else if (e && e.parameter && Object.keys(e.parameter).length > 0) {
      payload = e.parameter;
    } else {
      // Direct call fallback
      payload = {
        sheetName: "General Submissions",
        data: {
          "Reference ID": "INIT-001",
          "Status": "Webhook active and ready",
          "Note": "Run testSubmission() from the dropdown to verify"
        }
      };
    }

    var spreadsheet = SpreadsheetApp.getActiveSpreadsheet();
    if (!spreadsheet) {
      spreadsheet = SpreadsheetApp.create("The Affluentaccelerators - Submissions & Leads");
    }

    // Determine target sheet tab name
    var targetSheetName = payload.sheetName || payload.formName || payload.category || "General Submissions";

    // 1. Locate or create tab
    var sheet = spreadsheet.getSheetByName(targetSheetName);
    var isBrandNewSheet = false;
    if (!sheet) {
      sheet = spreadsheet.insertSheet(targetSheetName);
      isBrandNewSheet = true;

      // Clean default empty Sheet1 if first custom tab
      var defaultSheet = spreadsheet.getSheetByName("Sheet1");
      if (defaultSheet && defaultSheet.getLastRow() === 0 && spreadsheet.getSheets().length > 1) {
        try {
          spreadsheet.deleteSheet(defaultSheet);
        } catch (delErr) {}
      }
    }

    // 2. Extract row data
    var formData = payload.data || payload.formData || payload;
    var rowRecord = {};

    var timestampStr = "";
    try {
      var tz = (typeof Session !== "undefined" && Session.getScriptTimeZone) ? Session.getScriptTimeZone() : "GMT+01:00";
      timestampStr = Utilities.formatDate(new Date(), tz, "yyyy-MM-dd HH:mm:ss");
    } catch (dateErr) {
      timestampStr = new Date().toISOString();
    }

    rowRecord["Submission Time"] = payload.timestamp || timestampStr;
    if (payload.id) {
      rowRecord["Reference ID"] = payload.id;
    }

    // Populate submission fields
    for (var key in formData) {
      if (formData.hasOwnProperty(key)) {
        if (key !== 'sheetName' && key !== 'formName' && key !== 'data' && key !== 'formData' && key !== 'timestamp') {
          rowRecord[key] = formData[key];
        }
      }
    }

    // 3. Header management
    var lastRow = sheet.getLastRow();
    var lastCol = sheet.getLastColumn();
    var headers = [];

    if (lastRow === 0 || lastCol === 0 || isBrandNewSheet) {
      headers = Object.keys(rowRecord);

      if (headers.length > 0) {
        var headerRange = sheet.getRange(1, 1, 1, headers.length);
        headerRange.setValues([headers]);
        headerRange.setBackground("#06261b");
        headerRange.setFontColor("#f3c74d");
        headerRange.setFontWeight("bold");
        headerRange.setFontFamily("Arial");
        headerRange.setHorizontalAlignment("center");
        headerRange.setVerticalAlignment("middle");
        sheet.setRowHeight(1, 35);
        sheet.setFrozenRows(1);
      }
    } else {
      headers = sheet.getRange(1, 1, 1, lastCol).getValues()[0];

      for (var f in rowRecord) {
        if (rowRecord.hasOwnProperty(f)) {
          if (headers.indexOf(f) === -1) {
            headers.push(f);
            var newColIdx = headers.length;
            var newHeaderCell = sheet.getRange(1, newColIdx);
            newHeaderCell.setValue(f);
            newHeaderCell.setBackground("#06261b");
            newHeaderCell.setFontColor("#f3c74d");
            newHeaderCell.setFontWeight("bold");
            newHeaderCell.setFontFamily("Arial");
            newHeaderCell.setHorizontalAlignment("center");
            newHeaderCell.setVerticalAlignment("middle");
          }
        }
      }
    }

    // 4. Assemble row values matching header order
    var rowValues = [];
    for (var i = 0; i < headers.length; i++) {
      var colHeader = headers[i];
      var cellVal = rowRecord[colHeader];
      rowValues.push((cellVal !== undefined && cellVal !== null) ? cellVal : "");
    }

    sheet.appendRow(rowValues);
    var insertedRowIdx = sheet.getLastRow();

    // Style data row
    if (headers.length > 0) {
      var dataRange = sheet.getRange(insertedRowIdx, 1, 1, headers.length);
      dataRange.setVerticalAlignment("middle");
      dataRange.setFontFamily("Arial");
      sheet.setRowHeight(insertedRowIdx, 28);

      if (insertedRowIdx % 2 === 0) {
        dataRange.setBackground("#f8faf8");
      }

      for (var c = 1; c <= headers.length; c++) {
        sheet.autoResizeColumn(c);
        var width = sheet.getColumnWidth(c);
        sheet.setColumnWidth(c, Math.max(width + 20, 120));
      }
    }

    return ContentService.createTextOutput(JSON.stringify({
      status: "success",
      message: "Lead recorded in sheet: " + targetSheetName,
      sheet: targetSheetName,
      row: insertedRowIdx
    })).setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({
      status: "error",
      error: error.toString()
    })).setMimeType(ContentService.MimeType.JSON);

  } finally {
    lock.releaseLock();
  }
}

// GET endpoint
function doGet(e) {
  return ContentService.createTextOutput(JSON.stringify({
    status: "online",
    service: "The Affluentaccelerators Form Webhook",
    message: "Ready to accept form submissions into Google Sheets tabs."
  })).setMimeType(ContentService.MimeType.JSON);
}

